<?php
namespace OpenLMS\Controllers;

use OpenLMS\Core\Auth;
use OpenLMS\Core\Csrf;
use OpenLMS\Core\Database;
use OpenLMS\Policies\CoursePolicy;
use OpenLMS\Services\UploadService;

trait ProjectHelpersTrait
{
    private static function project(int $id):?array{$st=Database::connection()->prepare('SELECT p.*,c.title course_title,c.teacher_id,c.subject_id,c.status course_status,s.status subject_status FROM projects p JOIN courses c ON c.id=p.course_id JOIN subjects s ON s.id=c.subject_id WHERE p.id=?');$st->execute([$id]);return $st->fetch()?:null;}
    private static function course(int $id):?array{$st=Database::connection()->prepare("SELECT c.*,s.status subject_status FROM courses c JOIN subjects s ON s.id=c.subject_id WHERE c.id=?");$st->execute([$id]);return $st->fetch()?:null;}
    private static function canView(array $p,array $u):bool{return CoursePolicy::canManage($p,$u)||($p['status']==='published'&&CoursePolicy::canViewCourse(['id'=>$p['course_id'],'subject_id'=>$p['subject_id'],'teacher_id'=>$p['teacher_id'],'status'=>$p['course_status'],'subject_status'=>$p['subject_status']],$u));}
    private static function projectsForUser(array $u):array{$pdo=Database::connection();if(Auth::can('projects.manage')){$where=Auth::hasAnyRole(['super_admin','administrator','hod'])?'1=1':'c.teacher_id=?';$st=$pdo->prepare("SELECT p.*,c.title course_title,(SELECT COUNT(*) FROM project_submissions ps WHERE ps.project_id=p.id) submission_count FROM projects p JOIN courses c ON c.id=p.course_id WHERE $where ORDER BY p.id DESC");$st->execute($where==='1=1'?[]:[(int)$u['id']]);return $st->fetchAll();}$st=$pdo->prepare("SELECT DISTINCT p.*,c.title course_title,(SELECT COUNT(*) FROM project_submissions ps WHERE ps.project_id=p.id AND (ps.user_id=? OR ps.group_id IN (SELECT group_id FROM project_group_members WHERE user_id=?))) submission_count FROM projects p JOIN courses c ON c.id=p.course_id JOIN subjects s ON s.id=c.subject_id JOIN class_subjects cs ON cs.subject_id=s.id JOIN class_members cm ON cm.class_id=cs.class_id WHERE p.status='published' AND c.status='published' AND s.status='active' AND cm.user_id=? ORDER BY p.deadline_at");$st->execute([(int)$u['id'],(int)$u['id'],(int)$u['id']]);return $st->fetchAll();}
    private static function manageableCourses(array $u):array{$pdo=Database::connection();if(Auth::hasAnyRole(['super_admin','administrator','hod']))return $pdo->query("SELECT c.*,s.status subject_status FROM courses c JOIN subjects s ON s.id=c.subject_id WHERE c.status<>'archived' ORDER BY c.title")->fetchAll();$st=$pdo->prepare("SELECT c.*,s.status subject_status FROM courses c JOIN subjects s ON s.id=c.subject_id WHERE c.teacher_id=? AND c.status<>'archived' ORDER BY c.title");$st->execute([(int)$u['id']]);return $st->fetchAll();}
    private static function groups(int $pid):array{$pdo=Database::connection();$st=$pdo->prepare('SELECT * FROM project_groups WHERE project_id=? ORDER BY name');$st->execute([$pid]);$groups=$st->fetchAll();$members=$pdo->prepare('SELECT u.name FROM project_group_members gm JOIN users u ON u.id=gm.user_id WHERE gm.group_id=? ORDER BY u.name');foreach($groups as &$g){$members->execute([(int)$g['id']]);$g['members']=implode(', ',array_column($members->fetchAll(),'name'));}unset($g);return $groups;}
    private static function courseStudents(int $cid):array{$st=Database::connection()->prepare("SELECT DISTINCT u.id,u.name FROM courses c JOIN class_subjects cs ON cs.subject_id=c.subject_id JOIN class_members cm ON cm.class_id=cs.class_id JOIN users u ON u.id=cm.user_id WHERE c.id=? AND u.status='active' ORDER BY u.name");$st->execute([$cid]);return $st->fetchAll();}
    private static function studentHasCourse(int $uid,int $cid):bool{$st=Database::connection()->prepare("SELECT COUNT(*) FROM courses c JOIN class_subjects cs ON cs.subject_id=c.subject_id JOIN class_members cm ON cm.class_id=cs.class_id WHERE c.id=? AND cm.user_id=? AND c.status='published'");$st->execute([$cid,$uid]);return (int)$st->fetchColumn()>0;}
    private static function groupBelongs(int $gid,int $pid):bool{$st=Database::connection()->prepare('SELECT COUNT(*) FROM project_groups WHERE id=? AND project_id=?');$st->execute([$gid,$pid]);return (int)$st->fetchColumn()>0;}
    private static function groupMember(int $gid,int $uid):bool{$st=Database::connection()->prepare('SELECT COUNT(*) FROM project_group_members WHERE group_id=? AND user_id=?');$st->execute([$gid,$uid]);return (int)$st->fetchColumn()>0;}
    private static function submission(int $id):?array{$st=Database::connection()->prepare('SELECT * FROM project_submissions WHERE id=?');$st->execute([$id]);return $st->fetch()?:null;}
    private static function submissionsForProject(array $p,array $u,bool $manage):array{$pdo=Database::connection();if($manage){$st=$pdo->prepare('SELECT ps.*,u.name owner_name,pg.name group_name FROM project_submissions ps JOIN users u ON u.id=ps.user_id LEFT JOIN project_groups pg ON pg.id=ps.group_id WHERE ps.project_id=? ORDER BY ps.id DESC');$st->execute([(int)$p['id']]);}else{$st=$pdo->prepare('SELECT ps.*,u.name owner_name,pg.name group_name FROM project_submissions ps JOIN users u ON u.id=ps.user_id LEFT JOIN project_groups pg ON pg.id=ps.group_id WHERE ps.project_id=? AND (ps.user_id=? OR ps.group_id IN (SELECT group_id FROM project_group_members WHERE user_id=?)) ORDER BY ps.id DESC');$st->execute([(int)$p['id'],(int)$u['id'],(int)$u['id']]);}return $st->fetchAll();}
    private static function submissionFiles(int $sid):array{$st=Database::connection()->prepare('SELECT * FROM submission_files WHERE submission_id=? ORDER BY id');$st->execute([$sid]);return $st->fetchAll();}
    private static function humanizeStoredText(string $value):string
    {
        $value=trim($value);if($value==='')return '';$decoded=json_decode($value,true);if(!is_array($decoded))return $value;$lines=[];foreach($decoded as $key=>$item){if(is_scalar($item)||$item===null)$lines[]=(is_string($key)?$key.': ':'').(string)$item;}return $lines?implode("\n",$lines):$value;
    }
}
